  var AudioEngine = {
    ctx: null,
    init() {
      if (!this.ctx) {
        try {
          const AudioContextClass = window.AudioContext || window.webkitAudioContext;
          if (AudioContextClass) {
            this.ctx = new AudioContextClass();
          }
        } catch (e) {
          console.warn("Could not initialize AudioContext:", e);
        }
      }
    },
    play(type) {
      if (!state.soundEnabled) return;
      try {
        this.init();
        if (!this.ctx) return;
        const ctx = this.ctx;
        if (ctx.state === "suspended") {
          ctx.resume().catch((e) => console.warn("Failed to resume AudioContext:", e));
        }
        const now = ctx.currentTime;
        if (type === "click") {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.frequency.setValueAtTime(600, now);
          osc.frequency.exponentialRampToValueAtTime(150, now + 0.04);
          gain.gain.setValueAtTime(0.04, now);
          gain.gain.linearRampToValueAtTime(0, now + 0.04);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(now);
          osc.stop(now + 0.04);
        } else if (type === "flip") {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = "triangle";
          osc.frequency.setValueAtTime(280, now);
          osc.frequency.exponentialRampToValueAtTime(140, now + 0.12);
          gain.gain.setValueAtTime(0.06, now);
          gain.gain.linearRampToValueAtTime(0, now + 0.12);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(now);
          osc.stop(now + 0.12);
        } else if (type === "success") {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = "sine";
          osc.frequency.setValueAtTime(523.25, now);
          osc.frequency.setValueAtTime(659.25, now + 0.08);
          osc.frequency.setValueAtTime(783.99, now + 0.16);
          gain.gain.setValueAtTime(0.05, now);
          gain.gain.setValueAtTime(0.05, now + 0.08);
          gain.gain.setValueAtTime(0.05, now + 0.16);
          gain.gain.exponentialRampToValueAtTime(1e-3, now + 0.35);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start(now);
          osc.stop(now + 0.35);
        } else if (type === "fail") {
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = "sawtooth";
          osc.frequency.setValueAtTime(180, now);
          osc.frequency.linearRampToValueAtTime(90, now + 0.2);
          gain.gain.setValueAtTime(0.06, now);
          gain.gain.exponentialRampToValueAtTime(1e-3, now + 0.2);
          const filter = ctx.createBiquadFilter();
          filter.type = "lowpass";
          filter.frequency.setValueAtTime(450, now);
          osc.connect(filter);
          filter.connect(gain);
          gain.connect(ctx.destination);
          osc.start(now);
          osc.stop(now + 0.2);
        } else if (type === "cheer") {
          const notes = [523.25, 659.25, 783.99, 1046.5, 1318.51];
          notes.forEach((freq, idx) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = "sine";
            osc.frequency.setValueAtTime(freq, now + idx * 0.06);
            gain.gain.setValueAtTime(0, now);
            gain.gain.linearRampToValueAtTime(0.04, now + idx * 0.06 + 0.02);
            gain.gain.exponentialRampToValueAtTime(1e-3, now + idx * 0.06 + 0.3);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(now + idx * 0.06);
            osc.stop(now + idx * 0.06 + 0.3);
          });
        }
      } catch (e) {
        console.warn("Audio Context synth error:", e);
      }
    },
    speak(text, onStart, onEnd, onError) {
      if (!("speechSynthesis" in window)) {
        console.warn("Speech Synthesis not supported in this browser.");
        if (onError) onError();
        return;
      }
      window.speechSynthesis.cancel();
      if (!text) {
        if (onEnd) onEnd();
        return;
      }
      const cleanText = text.replace(/<[^>]*>/g, "").trim();
      try {
        const utterance = new SpeechSynthesisUtterance(cleanText);
        utterance.rate = 0.95;
        utterance.pitch = 1;
        const voices = window.speechSynthesis.getVoices();
        const enVoice = voices.find((v) => v.lang === "en-GB" || v.lang === "en-US") || voices.find((v) => v.lang.startsWith("en"));
        if (enVoice) {
          utterance.voice = enVoice;
        }
        utterance.onstart = () => {
          if (onStart) onStart();
        };
        utterance.onend = () => {
          if (onEnd) onEnd();
        };
        utterance.onerror = (e) => {
          console.warn("SpeechSynthesis error:", e);
          if (onError) onError();
        };
        window.speechSynthesis.speak(utterance);
      } catch (err) {
        console.warn("Speech synthesis error:", err);
        if (onError) onError();
      }
    },
    stopSpeaking() {
      if ("speechSynthesis" in window) {
        window.speechSynthesis.cancel();
      }
    }
  };

  // src/confetti.js
  var Confetti = {
    canvas: null,
    ctx: null,
    particles: [],
    animationId: null,
    init() {
      this.canvas = document.getElementById("confetti-canvas");
      if (!this.canvas) return;
      this.ctx = this.canvas.getContext("2d");
      this.resize();
      window.removeEventListener("resize", this.resizeBound);
      this.resizeBound = () => this.resize();
      window.addEventListener("resize", this.resizeBound);
    },
    resize() {
      if (this.canvas) {
        this.canvas.width = window.innerWidth;
        this.canvas.height = window.innerHeight;
      }
    },
    spawn(count = 80) {
      this.init();
      if (!this.ctx) return;
      if (this.animationId) {
        cancelAnimationFrame(this.animationId);
      }
      this.particles = [];
      const colors = ["#a855f7", "#6366f1", "#06b6d4", "#10b981", "#f43f5e", "#facc15"];
      for (let i = 0; i < count; i++) {
        this.particles.push({
          x: Math.random() * this.canvas.width,
          y: Math.random() * -this.canvas.height - 20,
          size: Math.random() * 8 + 6,
          color: colors[Math.floor(Math.random() * colors.length)],
          speedX: Math.random() * 4 - 2,
          speedY: Math.random() * 4 + 4,
          rotation: Math.random() * 360,
          rotationSpeed: Math.random() * 6 - 3,
          opacity: 1
        });
      }
      this.loop();
    },
    loop() {
      const ctx = this.ctx;
      if (!ctx) return;
      ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
      let active = false;
      this.particles.forEach((p) => {
        p.y += p.speedY;
        p.x += p.speedX;
        p.rotation += p.rotationSpeed;
        if (p.y > this.canvas.height - 20) {
          p.opacity -= 0.015;
        }
        if (p.opacity > 0) {
          active = true;
          ctx.save();
          ctx.translate(p.x, p.y);
          ctx.rotate(p.rotation * Math.PI / 180);
          ctx.fillStyle = p.color;
          ctx.globalAlpha = p.opacity;
          ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
          ctx.restore();
        }
      });
      if (active) {
        this.animationId = requestAnimationFrame(() => this.loop());
      } else {
        ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
      }
    }
  };

